        int[] last = new int[128];
        int left = 0;
        int best = 0;
        for (int right = 0; right < signal.length(); right++) {
            char symbol = signal.charAt(right);
            left = Math.max(left, last[symbol]);
            best = Math.max(best, right - left + 1);
            last[symbol] = right + 1;
